  "<span class=\"quando\">hoje</span><span><a href=\"wiki.html#/calabouco/{a}\">{b}</a> <small>+{bonus}% de saque</small></span>": "<span class=\"quando\">hoy</span><span><a href=\"wiki.html#/calabouco/{a}\">{b}</a> <small>+{bonus}% de botín</small></span>",
