  "<div class=\"pacotes-cab\">{a}<h3>Barras de Ouro</h3>{b}</div><p class=\"apoio\">{c}</p><div class=\"pacotes\">{d}</div>": "<div class=\"pacotes-cab\">{a}<h3>Barras de Oro</h3>{b}</div><p class=\"apoio\">{c}</p><div class=\"pacotes\">{d}</div>",
