  "Busca": "Búsqueda",
  "<h1>Busca</h1><p class=\"wk-sub\">Digite pelo menos duas letras no campo da busca.</p>": "<h1>Búsqueda</h1><p class=\"wk-sub\">Escribe al menos dos letras en el campo de búsqueda.</p>",
  "<h1>Busca: {a}</h1><p class=\"wk-contagem\">{b}</p>{c}": "<h1>Búsqueda: {a}</h1><p class=\"wk-contagem\">{b}</p>{c}",
